CREATE SCHEMA gudang;

CREATE TABLE gudang.stok (
  id      bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  sku     text NOT NULL UNIQUE,
  jumlah  integer NOT NULL DEFAULT 0
);

INSERT INTO gudang.stok (sku, jumlah) VALUES ('KOPI-GAYO', 40), ('TEH-MELATI', 120)
RETURNING id, sku;

SHOW search_path;                    -- "$user", public
SET search_path = penjualan, public;
SELECT nama, kota FROM pelanggan;    -- yang dibaca: penjualan.pelanggan

INSERT INTO penjualan.pelanggan (id, nama) VALUES (99, 'Sari');
-- ERROR: cannot insert a non-DEFAULT value into column "id"

INSERT INTO penjualan.pelanggan (nama) VALUES ('Sari') RETURNING id;

CREATE TABLE jadwal (acara text, mulai timestamptz NOT NULL);
INSERT INTO jadwal VALUES ('Webinar SQL', '2026-11-20 09:00+07');

SET TIME ZONE 'Asia/Jakarta';  SELECT mulai FROM jadwal;  -- 09:00+07
SET TIME ZONE 'Asia/Makassar'; SELECT mulai FROM jadwal;  -- 10:00+08

INSERT INTO produk (nama, harga) VALUES ('Kopi Gayo', 85000);
INSERT INTO pesanan (produk_id, jumlah) VALUES (1, 2);

DELETE FROM produk WHERE id = 1;
-- ERROR: update or delete on table "produk" violates foreign key constraint

CREATE TABLE promo (
  kode     text PRIMARY KEY,
  mulai    date NOT NULL,
  selesai  date NOT NULL,
  diskon   numeric(5,2) NOT NULL,
  CONSTRAINT promo_tanggal_benar CHECK (selesai > mulai),
  CONSTRAINT promo_diskon_wajar  CHECK (diskon BETWEEN 0 AND 90)
);
INSERT INTO promo VALUES ('GAJIAN', '2026-11-25', '2026-11-20', 10);
-- ERROR: ... violates check constraint "promo_tanggal_benar"

CREATE TABLE webhook (
  id        bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  diterima  timestamptz NOT NULL DEFAULT now(),
  payload   jsonb NOT NULL
);
INSERT INTO webhook (payload) VALUES
  ('{"order_id": "INV-1001", "status": "settlement", "amount": "125000"}');

SELECT payload->>'order_id' AS pesanan, (payload->>'amount')::numeric AS nominal
FROM webhook
WHERE payload @> '{"status": "settlement"}';

UPDATE produk
SET spek = jsonb_set(spek, '{berat_g}', '500')
WHERE nama = 'Kopi Gayo';

SELECT spek FROM produk WHERE nama = 'Kopi Gayo';

CREATE TYPE status_pesanan AS ENUM ('baru', 'dibayar', 'dikirim', 'selesai');

CREATE TABLE log_login (
  pengguna  text NOT NULL,
  ip        inet NOT NULL,
  waktu     timestamptz NOT NULL DEFAULT now()
);
INSERT INTO log_login (pengguna, ip) VALUES ('rina', '10.0.1.25'), ('budi', '182.253.10.4');

SELECT pengguna, ip FROM log_login WHERE ip << '10.0.0.0/8';  -- login dari jaringan kantor

CREATE ROLE webapp LOGIN PASSWORD 'ganti_di_vault';
GRANT USAGE ON SCHEMA penjualan TO webapp;
GRANT SELECT, INSERT, UPDATE ON penjualan.pelanggan TO webapp;

CREATE ROLE cs_magang LOGIN PASSWORD 'ganti_di_vault';
GRANT USAGE ON SCHEMA penjualan TO cs_magang;
GRANT SELECT (id, nama, kota) ON penjualan.pelanggan TO cs_magang;

SET ROLE cs_magang;
SELECT nama, kota FROM penjualan.pelanggan;   -- berhasil
SELECT email FROM penjualan.pelanggan;        -- ERROR: permission denied
RESET ROLE;

CREATE TABLE pesanan_app (
  id            bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  pelanggan_id  bigint NOT NULL,
  total         numeric(12,0) NOT NULL
);
ALTER TABLE pesanan_app ENABLE ROW LEVEL SECURITY;
CREATE POLICY pesanan_sendiri ON pesanan_app
  USING (pelanggan_id = current_setting('app.pelanggan_id')::bigint);

CREATE POLICY kasir_baca ON pesanan_toko FOR SELECT
  USING (toko = current_setting('app.toko'));

CREATE POLICY kasir_tambah ON pesanan_toko FOR INSERT
  WITH CHECK (toko = current_setting('app.toko'));

SELECT tablename, policyname, cmd, qual, with_check
FROM pg_policies
ORDER BY tablename, policyname;

BEGIN;
UPDATE gudang.stok SET jumlah = jumlah - 2 WHERE sku = 'KOPI-GAYO';
INSERT INTO pesanan (produk_id, jumlah) VALUES (1, 2);
COMMIT;

BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT sum(saldo) AS total FROM rekening;
-- transaksi lain boleh COMMIT di sini, angka di bawah tetap sama
SELECT no, saldo FROM rekening ORDER BY no;
COMMIT;

BEGIN ISOLATION LEVEL SERIALIZABLE;
SELECT count(*) FROM jadwal_dokter WHERE dokter = 'dr. Rina' AND tanggal = '2026-11-20';
INSERT INTO jadwal_dokter (dokter, tanggal, pasien) VALUES ('dr. Rina', '2026-11-20', 'Budi');
COMMIT;
-- ERROR: could not serialize access due to read/write dependencies among transactions
-- -> ulangi transaksi dari BEGIN

BEGIN;
SELECT qty FROM stok WHERE sku = 'KOPI' FOR UPDATE;
UPDATE stok SET qty = qty - 1 WHERE sku = 'KOPI';
COMMIT;

BEGIN;
SELECT id, jenis FROM tugas
WHERE status = 'antre'
ORDER BY id
LIMIT 1
FOR UPDATE SKIP LOCKED;
-- kerjakan tugasnya, lalu:
UPDATE tugas SET status = 'selesai' WHERE id = 42;
COMMIT;

BEGIN;
SELECT sku FROM stok WHERE sku IN ('GULA', 'KOPI') ORDER BY sku FOR UPDATE;
UPDATE stok SET qty = qty - 1 WHERE sku IN ('GULA', 'KOPI');
COMMIT;

SELECT pid, relid::regclass AS tabel, phase,
       round(100.0 * heap_blks_scanned / nullif(heap_blks_total, 0), 1) AS persen
FROM pg_stat_progress_vacuum;

EXPLAIN (ANALYZE) SELECT * FROM pesanan WHERE status = 'batal';
ANALYZE pesanan;
EXPLAIN (ANALYZE) SELECT * FROM pesanan WHERE status = 'batal';

BEGIN;
EXPLAIN (ANALYZE, BUFFERS)
UPDATE pesanan SET status = 'selesai' WHERE status = 'dikirim' AND dibuat < now() - interval '14 days';
ROLLBACK;

CREATE INDEX CONCURRENTLY pesanan_baru_idx
  ON pesanan (dibuat)
  WHERE status = 'baru';

EXPLAIN SELECT id FROM pesanan WHERE status = 'baru' AND dibuat < now() - interval '1 day';

CREATE INDEX log_akses_waktu_brin ON log_akses USING brin (waktu);

EXPLAIN SELECT count(*) FROM log_akses
WHERE waktu >= '2026-11-01' AND waktu < '2026-11-02';

BEGIN;
SET LOCAL work_mem = '256MB';
SELECT pelanggan_id, sum(total) FROM pesanan GROUP BY pelanggan_id ORDER BY 2 DESC;
COMMIT;

ALTER SYSTEM SET random_page_cost = 1.1;
ALTER SYSTEM SET effective_cache_size = '12GB';
ALTER SYSTEM SET shared_buffers = '4GB';
SELECT pg_reload_conf();

SELECT name, setting, pending_restart FROM pg_settings WHERE pending_restart;

SELECT now() - pg_last_xact_replay_timestamp() AS lag_waktu,
       pg_last_wal_receive_lsn() AS diterima,
       pg_last_wal_replay_lsn() AS diputar;

ALTER SYSTEM SET log_min_duration_statement = '500ms';
